import {ResponseError} from '@github-ui/react-core/future/response-error'
import type {UseMutationOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import type {PolicyResponse, UpdatePolicyRequest} from '../types'
import {policyEndpoint} from './use-policy-query'

export function updatePolicyMutationOptions(
  enterpriseSlug: string,
): UseMutationOptions<PolicyResponse, ResponseError, UpdatePolicyRequest> {
  return {
    async mutationFn(update) {
      // Rails treats an absent `severityThreshold` as "unspecified" and its validator
      // (%w[low medium high critical]) won't accept the sentinel `'none'` we use in the
      // form, so omit the key from the wire payload when the user has it disabled.
      const {severityThreshold, ...rest} = update.policy
      const wirePolicy = severityThreshold === 'none' ? rest : {...rest, severityThreshold}

      const response = await reactFetchJSON(policyEndpoint(enterpriseSlug), {
        method: 'PATCH',
        body: {policy: wirePolicy},
      })

      if (!response.ok) {
        throw new ResponseError('Failed to update package firewall policy.', response)
      }

      return (await response.json()) as PolicyResponse
    },
  }
}
