import type {PackageOverride} from '../types'

/**
 * Stable string identity for an override row. Used both as a React key in lists and as a
 * Set key when staging removals — `ecosystem` + `name` + `version` is the natural primary
 * key for an override and matches the tuple Rails uniques on.
 */
export function overrideKey(o: Pick<PackageOverride, 'ecosystem' | 'name' | 'version'>): string {
  return `${o.ecosystem}::${o.name}::${o.version ?? ''}`
}
