import {mainQuery} from '@github-ui/react-core/future/main-query'
import {packageFirewallEnterpriseSettingsAppBuilder} from '../config/app-builder'
import type {PackageFirewallRoutePayload} from '../types'

// The route id `packageFirewallEnterpriseSettingsRoute` matches the camelCase key the
// dotcom controller emits in `embeddedData.payload`. Keep the path in sync with
// `enterprise_package_firewall_path` in the github/github Rails app.
export const packageFirewallEnterpriseSettingsRoute =
  packageFirewallEnterpriseSettingsAppBuilder.createQueryRouteConfig('packageFirewallEnterpriseSettingsRoute', {
    path: '/enterprises/:enterprise/settings/policies/package_firewall',
    queries: [mainQuery<PackageFirewallRoutePayload>()],
  })
