import {Heading} from '@primer/react'
import {ChevronRightIcon} from '@primer/octicons-react'
import styles from './OverridesNavCard.module.css'

interface OverridesNavCardProps {
  allowedTotal: number
  blockedTotal: number
  onClick: () => void
}

export function OverridesNavCard({allowedTotal, blockedTotal, onClick}: OverridesNavCardProps) {
  const parts: string[] = []
  if (allowedTotal > 0) parts.push(`${allowedTotal} allowed`)
  if (blockedTotal > 0) parts.push(`${blockedTotal} blocked`)
  const subtitle = parts.join(' · ')

  return (
    <div>
      <div className={styles.headingWrapper}>
        <Heading as="h3" className="f4">
          Overrides
        </Heading>
        <p className={styles.description}>Define which packages can override firewall settings.</p>
      </div>
      <button type="button" onClick={onClick} className={styles.navButton}>
        <div className={styles.navButtonContent}>
          <span className={styles.navButtonTitle}>Package overrides</span>
          {subtitle ? <span className={styles.navButtonSubtitle}>{subtitle}</span> : null}
        </div>
        <ChevronRightIcon size={16} />
      </button>
    </div>
  )
}
