import styles from './PatternExamples.module.css'

interface PatternExamplesProps {
  /** Caption sentence shown before the examples list. */
  description: string
  examples: string[]
}

export function PatternExamples({description, examples}: PatternExamplesProps) {
  return (
    <>
      <span className={styles.descriptionText}>{description}</span>
      <span className={styles.examplesText}>
        <span>Examples: </span>
        <code className={styles.examplesCode}>{examples.join(', ')}</code>
      </span>
    </>
  )
}
