import {ResponseError} from '@github-ui/react-core/future/response-error'
import type {UseMutationOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import type {RemoveOverrideRequest} from '../types'

export async function removeOverride(enterpriseSlug: string, request: RemoveOverrideRequest): Promise<void> {
  const response = await reactFetchJSON(
    `/enterprises/${enterpriseSlug}/settings/policies/package_firewall/overrides/delete`,
    {method: 'POST', body: request},
  )

  if (!response.ok) {
    throw new ResponseError('Failed to remove package override.', response)
  }
}

export function removeOverrideMutationOptions(
  enterpriseSlug: string,
): UseMutationOptions<void, ResponseError, RemoveOverrideRequest> {
  return {
    mutationFn: request => removeOverride(enterpriseSlug, request),
  }
}
