import {useState} from 'react'
import {Button, FormControl, Select, TextInput} from '@primer/react'
import {Dialog} from '@primer/react/deprecated'
import styles from './AddPackageRuleDialog.module.css'
import {PatternExamples} from './PatternExamples'
import {patternHintsFor} from '../lib/pattern-hints'
import type {OverrideType, PackageEcosystem} from '../types'

interface AddPackageRuleDialogProps {
  isOpen: boolean
  mode: OverrideType
  isSubmitting?: boolean
  errorMessage?: string
  onClose: () => void
  onAdd: (input: {ecosystem: PackageEcosystem; name: string; version: string}) => void
}

const ECOSYSTEM_OPTIONS: ReadonlyArray<{value: PackageEcosystem; label: string}> = [{value: 'npm', label: 'npm'}]

export function AddPackageRuleDialog({
  isOpen,
  mode,
  isSubmitting,
  errorMessage,
  onClose,
  onAdd,
}: AddPackageRuleDialogProps) {
  const [ecosystem, setEcosystem] = useState<PackageEcosystem>('npm')
  const [name, setName] = useState('')
  const [version, setVersion] = useState('')
  const [error, setError] = useState('')
  // Track the inputs that produced the most recent server error so we can hide it the
  // moment the user starts editing — otherwise a stale server error would linger above
  // a now-corrected form.
  const [submittedSnapshot, setSubmittedSnapshot] = useState<string | null>(null)

  const isBlock = mode === 'deny'
  const title = isBlock ? 'Add blocked package' : 'Add allowed package'
  const currentSnapshot = `${ecosystem}::${name}::${version}`
  const showServerError = Boolean(errorMessage) && submittedSnapshot === currentSnapshot
  const displayError = error || (showServerError ? errorMessage : '')
  const hints = patternHintsFor(ecosystem)

  const handleSubmit = () => {
    const trimmedName = name.trim()
    if (!trimmedName) {
      setError('Package name is required')
      return
    }
    setSubmittedSnapshot(currentSnapshot)
    onAdd({ecosystem, name: trimmedName, version: version.trim()})
  }

  const handleClose = () => {
    if (isSubmitting) return
    setEcosystem('npm')
    setName('')
    setVersion('')
    setError('')
    setSubmittedSnapshot(null)
    onClose()
  }

  if (!isOpen) return null

  return (
    <Dialog isOpen={isOpen} onDismiss={handleClose} aria-label={title}>
      <Dialog.Header>{title}</Dialog.Header>
      <div className={styles.dialogBody}>
        <FormControl>
          <FormControl.Label>Ecosystem</FormControl.Label>
          <Select value={ecosystem} onChange={e => setEcosystem(e.target.value as PackageEcosystem)}>
            {ECOSYSTEM_OPTIONS.map(opt => (
              <Select.Option key={opt.value} value={opt.value}>
                {opt.label}
              </Select.Option>
            ))}
          </Select>
        </FormControl>

        <FormControl>
          <FormControl.Label>Package name</FormControl.Label>
          <TextInput
            value={name}
            onChange={e => {
              setName(e.target.value)
              setError('')
            }}
            validationStatus={displayError ? 'error' : undefined}
            block
          />
          <FormControl.Caption>
            <PatternExamples description={hints.nameDescription} examples={hints.nameExamples} />
          </FormControl.Caption>
          <div aria-live="assertive">
            {displayError ? <FormControl.Validation variant="error">{displayError}</FormControl.Validation> : null}
          </div>
        </FormControl>

        <FormControl>
          <FormControl.Label>Version (optional)</FormControl.Label>
          <TextInput value={version} onChange={e => setVersion(e.target.value)} block />
          <FormControl.Caption>
            <PatternExamples description={hints.versionDescription} examples={hints.versionExamples} />
          </FormControl.Caption>
        </FormControl>

        <div className={styles.dialogFooter}>
          <Button onClick={handleClose} disabled={isSubmitting}>
            Cancel
          </Button>
          <Button variant={isBlock ? 'danger' : 'primary'} onClick={handleSubmit} disabled={isSubmitting}>
            {isSubmitting ? 'Saving…' : title}
          </Button>
        </div>
      </div>
    </Dialog>
  )
}
