import {ResponseError} from '@github-ui/react-core/future/response-error'
import type {UseMutationOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import type {AddOverrideRequest, PackageOverride} from '../types'

export async function addOverride(enterpriseSlug: string, request: AddOverrideRequest): Promise<PackageOverride[]> {
  const response = await reactFetchJSON(`/enterprises/${enterpriseSlug}/settings/policies/package_firewall/overrides`, {
    method: 'POST',
    body: request,
  })

  if (!response.ok) {
    throw new ResponseError('Failed to add package override.', response)
  }

  // Rails returns the full updated list (allow or deny) for this override type, not
  // just the newly-added identifier.
  return (await response.json()) as PackageOverride[]
}

export function addOverrideMutationOptions(
  enterpriseSlug: string,
): UseMutationOptions<PackageOverride[], ResponseError, AddOverrideRequest> {
  return {
    mutationFn: request => addOverride(enterpriseSlug, request),
  }
}
