import {ConfirmationDialog} from '@primer/react'
import styles from './DeleteOverrideDialog.module.css'
import type {OverrideType, PackageOverride} from '../types'

interface DeleteOverrideDialogProps {
  override: PackageOverride
  variant: OverrideType
  isPending?: boolean
  onCancel: () => void
  onConfirm: () => void
}

export function DeleteOverrideDialog({override, variant, isPending, onCancel, onConfirm}: DeleteOverrideDialogProps) {
  const isBlock = variant === 'deny'
  const variantLabel = isBlock ? 'blocked packages' : 'allowed packages'
  const consequence = isBlock ? 'may be allowed by other firewall rules' : 'may be blocked by other firewall rules'

  const versionSuffix = override.version ? ` ${override.version}` : ''

  return (
    <ConfirmationDialog
      title={`Delete from ${variantLabel}`}
      confirmButtonContent="Delete"
      confirmButtonType="danger"
      confirmButtonLoading={isPending}
      cancelButtonLoading={isPending}
      onClose={gesture => {
        if (gesture === 'confirm') {
          onConfirm()
        } else if (!isPending) {
          onCancel()
        }
      }}
    >
      <span>
        Deleting{' '}
        <span className={styles.boldText}>
          {override.name}
          {versionSuffix}
        </span>{' '}
        from {variantLabel} means that future installations of this package {consequence}.
      </span>
    </ConfirmationDialog>
  )
}
