import {useState} from 'react'
import {Banner, Heading, Label} from '@primer/react'
import styles from './PackageFirewallEnterpriseSettings.module.css'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {PolicySettingsTab} from './components/PolicySettingsTab'
import {PackageOverridesTab} from './components/PackageOverridesTab'
import {OverridesNavCard} from './components/OverridesNavCard'
import {PageBackLink} from './components/PageBackLink'
import {RegistryConfigurationCard} from './components/RegistryConfigurationCard'
import {usePolicyQuery} from './queries/use-policy-query'
import {useOverridesQuery} from './queries/use-overrides-query'
import {withPolicyDefaults} from './lib/policy-defaults'
import type {PackageFirewallPayload} from './types'

type View = 'general' | 'overrides'

export function PackageFirewallEnterpriseSettings({
  enterpriseSlug,
  policy,
  allowedPackages,
  blockedPackages,
}: PackageFirewallPayload) {
  const isEnabled = isFeatureEnabled('package_firewall_enterprise_policy_ui')
  const [view, setView] = useState<View>('general')
  const [saveError, setSaveError] = useState<string | null>(null)

  const policyQuery = usePolicyQuery({
    enterpriseSlug,
    initialData: {policy},
  })
  const allowedQuery = useOverridesQuery({
    enterpriseSlug,
    type: 'allow',
    initialData: allowedPackages,
  })
  const blockedQuery = useOverridesQuery({
    enterpriseSlug,
    type: 'deny',
    initialData: blockedPackages,
  })

  if (!isEnabled) {
    return null
  }

  const allowed = allowedQuery.data ?? allowedPackages
  const blocked = blockedQuery.data ?? blockedPackages
  // Rails sends `policy: {}` when the enterprise has never saved a policy. Fill in defaults
  // so policy form fields don't render `NaN days` / blank dropdowns.
  const currentPolicy = withPolicyDefaults(policyQuery.data?.policy ?? policy)

  const goGeneral = () => setView('general')

  return (
    <>
      {view === 'overrides' ? (
        <>
          <PageBackLink onClick={goGeneral} />
          <PackageOverridesTab enterpriseSlug={enterpriseSlug} allowedPackages={allowed} blockedPackages={blocked} />
        </>
      ) : (
        <>
          <div className={styles.headerRow}>
            <Heading as="h2" className="f3">
              Package firewall
            </Heading>
            <Label variant="success">Preview</Label>
          </div>
          <p className={styles.description}>
            Control which packages can be installed across your enterprise. Configure blocking rules, then fine-tune
            with package overrides.
          </p>

          {saveError ? (
            <div className={styles.errorBanner}>
              <Banner
                variant="critical"
                title="Save failed"
                hideTitle
                description={saveError}
                onDismiss={() => setSaveError(null)}
              />
            </div>
          ) : null}

          <div className={styles.contentColumn}>
            <RegistryConfigurationCard enterpriseSlug={enterpriseSlug} />
            <OverridesNavCard
              allowedTotal={allowed.length}
              blockedTotal={blocked.length}
              onClick={() => setView('overrides')}
            />
            <PolicySettingsTab
              enterpriseSlug={enterpriseSlug}
              policy={currentPolicy}
              onSaveError={setSaveError}
              onSaveStart={() => setSaveError(null)}
            />
          </div>
        </>
      )}
    </>
  )
}
