import type {PolicySettings} from '../types'

/**
 * Default `PolicySettings` representing an unconfigured firewall: malware blocking off, no
 * advisory severity threshold, no supply-chain checks, no minimum age. Mirrors what the
 * Rails controller treats as "no policy".
 *
 * The dotcom controller emits an empty `{}` in the route payload when the enterprise has
 * never saved a policy, so the wire shape is `Partial<PolicySettings>` even though the
 * type declares it as `PolicySettings`. `withPolicyDefaults` normalizes that into a fully
 * populated object so the UI never has to read `undefined` / render `NaN days`.
 */
export const DEFAULT_POLICY: PolicySettings = {
  blockMalware: false,
  severityThreshold: 'none',
  blockAttestationDowngrade: false,
  blockAddedScripts: false,
  minimumPackageAge: 0,
}

export function withPolicyDefaults(policy: Partial<PolicySettings> | undefined | null): PolicySettings {
  // Strip nullish values from the input so explicit `null`s from the server (notably
  // `severityThreshold: null` when the proto returns `:SEVERITY_UNSPECIFIED`) don't shadow
  // the defaults below.
  const cleaned = Object.fromEntries(Object.entries(policy ?? {}).filter(([, v]) => v != null))
  return {...DEFAULT_POLICY, ...cleaned}
}
