import {useMemo, useState, type Ref} from 'react'
import {Button, Heading, IconButton, TextInput, VisuallyHidden} from '@primer/react'
import {Blankslate, DataTable, Table} from '@primer/react/experimental'
import {CheckCircleIcon, SearchIcon, TrashIcon, XCircleIcon, XIcon} from '@primer/octicons-react'
import {overrideKey} from '../lib/override-key'
import type {OverrideType, PackageOverride} from '../types'
import styles from './PackageOverridesList.module.css'

interface PackageOverridesListProps {
  overrides: PackageOverride[]
  variant: OverrideType
  addButtonRef?: Ref<HTMLButtonElement>
  onAdd: () => void
  onRemove: (override: PackageOverride, triggerEl: HTMLButtonElement | null) => void
}

const formatOverride = (o: PackageOverride) => `${o.name}${o.version ? `@${o.version}` : '@*'}`

type Row = PackageOverride & {id: string}

export function PackageOverridesList({overrides, variant, addButtonRef, onAdd, onRemove}: PackageOverridesListProps) {
  const [filter, setFilter] = useState('')
  const isBlock = variant === 'deny'

  const headingTitle = isBlock ? 'Blocked packages' : 'Allowed packages'
  const headingDescription = isBlock
    ? 'Packages that are always rejected, even if they would otherwise be allowed.'
    : 'Packages that can bypass any blocking firewall rules.'
  const variantLabel = isBlock ? 'blocked packages' : 'allowed packages'

  const rows = useMemo<Row[]>(() => {
    const lowerFilter = filter.toLowerCase()
    return overrides.filter(o => o.name.toLowerCase().includes(lowerFilter)).map(o => ({...o, id: overrideKey(o)}))
  }, [overrides, filter])

  return (
    <div>
      <div className={styles.headerRow}>
        <div className={styles.headerContent}>
          <Heading as="h3" variant="medium">
            {headingTitle}
          </Heading>
          <p className={styles.headerDescription}>{headingDescription}</p>
        </div>
        <div className={styles.buttonWrapper}>
          <Button ref={addButtonRef} onClick={onAdd}>
            Add package
          </Button>
        </div>
      </div>

      {overrides.length > 3 ? (
        <div className={styles.searchWrapper}>
          <TextInput
            leadingVisual={SearchIcon}
            aria-label={`Filter ${headingTitle.toLowerCase()}`}
            placeholder="Search or filter"
            value={filter}
            onChange={e => setFilter(e.target.value)}
            block
            trailingAction={
              filter ? <TextInput.Action onClick={() => setFilter('')} icon={XIcon} aria-label="Clear" /> : undefined
            }
          />
        </div>
      ) : null}

      {rows.length === 0 ? (
        filter ? (
          <div className={styles.emptyFilterContainer} role="status">
            <span className={styles.emptyFilterMessage}>No packages match your filter.</span>
          </div>
        ) : (
          <Blankslate border size="small">
            <Blankslate.Visual>
              {isBlock ? <XCircleIcon size="medium" /> : <CheckCircleIcon size="medium" />}
            </Blankslate.Visual>
            <Blankslate.Heading>
              {isBlock
                ? 'Blocked packages cannot be installed in your enterprise'
                : 'Allowed packages can install in your enterprise'}
            </Blankslate.Heading>
            <Blankslate.Description>
              {isBlock ? 'Use this list to block dangerous packages.' : 'Use this list to allow trusted packages.'}
            </Blankslate.Description>
          </Blankslate>
        )
      ) : (
        <Table.Container>
          <DataTable
            aria-label={headingTitle}
            data={rows}
            cellPadding="spacious"
            columns={[
              {
                id: 'package',
                header: () => (
                  <span className={styles.headerCountText}>
                    {`${rows.length} ${rows.length === 1 ? 'package' : 'packages'}`}
                  </span>
                ),
                rowHeader: true,
                renderCell: row => (
                  <div className={styles.cellColumnLayout}>
                    <span className={styles.packageName}>{formatOverride(row)}</span>
                    <span className={styles.ecosystemLabel}>{row.ecosystem}</span>
                  </div>
                ),
              },
              {
                id: 'actions',
                header: () => <VisuallyHidden>Actions</VisuallyHidden>,
                width: '48px',
                align: 'end',
                renderCell: row => (
                  <IconButton
                    icon={TrashIcon}
                    aria-label={`Delete ${row.ecosystem} ${formatOverride(row)} from ${variantLabel}`}
                    variant="invisible"
                    size="small"
                    onClick={event => onRemove(row, event.currentTarget)}
                  />
                ),
              },
            ]}
          />
        </Table.Container>
      )}
    </div>
  )
}
