import {useRef, useState} from 'react'
import {Heading, UnderlineNav} from '@primer/react'
import styles from './PackageOverridesTab.module.css'
import {useMutation, useQueryClient} from '@github-ui/react-query'
import {AddPackageRuleDialog} from './AddPackageRuleDialog'
import {DeleteOverrideDialog} from './DeleteOverrideDialog'
import {PackageOverridesList} from './PackageOverridesList'
import {addOverride} from '../queries/add-override'
import {removeOverride} from '../queries/remove-override'
import {getOverridesQueryKey} from '../queries/use-overrides-query'
import {overrideKey} from '../lib/override-key'
import type {OverrideType, PackageOverride} from '../types'

interface PackageOverridesTabProps {
  enterpriseSlug: string
  allowedPackages: PackageOverride[]
  blockedPackages: PackageOverride[]
}

interface PendingDelete {
  type: OverrideType
  override: PackageOverride
}

export function PackageOverridesTab({enterpriseSlug, allowedPackages, blockedPackages}: PackageOverridesTabProps) {
  const [activeTab, setActiveTab] = useState<OverrideType>('allow')
  const [dialogMode, setDialogMode] = useState<OverrideType | null>(null)
  const [addError, setAddError] = useState<string | null>(null)
  const [pendingDelete, setPendingDelete] = useState<PendingDelete | null>(null)
  const [deleteError, setDeleteError] = useState<string | null>(null)
  const queryClient = useQueryClient()

  // Track the trigger that opened a dialog so we can return focus to it after close.
  const addButtonRef = useRef<HTMLButtonElement | null>(null)
  const deleteTriggerRef = useRef<HTMLButtonElement | null>(null)

  const addMutation = useMutation({
    mutationFn: (input: {type: OverrideType; override: PackageOverride}) =>
      addOverride(enterpriseSlug, {
        type: input.type,
        ecosystem: input.override.ecosystem,
        name: input.override.name,
        version: input.override.version || undefined,
      }),
    onSuccess: (list, {type}) => {
      queryClient.setQueryData<PackageOverride[]>(getOverridesQueryKey(enterpriseSlug, type), list)
    },
  })

  const removeMutation = useMutation({
    mutationFn: (input: PendingDelete) =>
      removeOverride(enterpriseSlug, {
        type: input.type,
        ecosystem: input.override.ecosystem,
        name: input.override.name,
        version: input.override.version,
      }),
    onSuccess: (_data, {type, override}) => {
      const key = overrideKey(override)
      const queryKey = getOverridesQueryKey(enterpriseSlug, type)
      const baseline = type === 'allow' ? allowedPackages : blockedPackages
      const current = queryClient.getQueryData<PackageOverride[]>(queryKey) ?? baseline
      queryClient.setQueryData<PackageOverride[]>(
        queryKey,
        current.filter(o => overrideKey(o) !== key),
      )
    },
  })

  const allowedDisplay = allowedPackages
  const blockedDisplay = blockedPackages
  const visiblePackages = activeTab === 'allow' ? allowedDisplay : blockedDisplay

  const onAddSubmit = async (input: {ecosystem: PackageOverride['ecosystem']; name: string; version: string}) => {
    if (dialogMode === null) return
    setAddError(null)
    try {
      await addMutation.mutateAsync({type: dialogMode, override: input})
      setDialogMode(null)
      addButtonRef.current?.focus()
    } catch {
      setAddError("Couldn't add package. Please try again.")
    }
  }

  const onAddClose = () => {
    setDialogMode(null)
    setAddError(null)
    addButtonRef.current?.focus()
  }

  const onRequestDelete = (override: PackageOverride, triggerEl: HTMLButtonElement | null) => {
    deleteTriggerRef.current = triggerEl
    setDeleteError(null)
    setPendingDelete({type: activeTab, override})
  }

  const onConfirmDelete = async () => {
    if (!pendingDelete) return
    try {
      await removeMutation.mutateAsync(pendingDelete)
      setPendingDelete(null)
      // After a successful delete the row is gone, so return focus to a stable element.
      addButtonRef.current?.focus()
    } catch {
      setDeleteError("Couldn't delete package. Please try again.")
    }
  }

  const onCancelDelete = () => {
    setPendingDelete(null)
    setDeleteError(null)
    deleteTriggerRef.current?.focus()
  }

  return (
    <div className={styles.container}>
      <div className={styles.headingWrapper}>
        <Heading as="h2" className="f3">
          Package overrides
        </Heading>
        <p className={styles.description}>Define which packages can override firewall settings.</p>
      </div>

      <div className={styles.alertContainer} role="alert">
        {deleteError ? <span className={styles.dangerText}>{deleteError}</span> : null}
      </div>

      <UnderlineNav aria-label="Package overrides">
        <UnderlineNav.Item
          as="button"
          aria-current={activeTab === 'allow' ? 'page' : undefined}
          onSelect={() => setActiveTab('allow')}
          counter={allowedDisplay.length || undefined}
        >
          Allowed
        </UnderlineNav.Item>
        <UnderlineNav.Item
          as="button"
          aria-current={activeTab === 'deny' ? 'page' : undefined}
          onSelect={() => setActiveTab('deny')}
          counter={blockedDisplay.length || undefined}
        >
          Blocked
        </UnderlineNav.Item>
      </UnderlineNav>

      <PackageOverridesList
        key={activeTab}
        overrides={visiblePackages}
        variant={activeTab}
        addButtonRef={addButtonRef}
        onAdd={() => {
          setAddError(null)
          setDialogMode(activeTab)
        }}
        onRemove={(override, triggerEl) => onRequestDelete(override, triggerEl)}
      />

      {dialogMode ? (
        <AddPackageRuleDialog
          isOpen
          mode={dialogMode}
          isSubmitting={addMutation.isPending}
          errorMessage={addError ?? undefined}
          onClose={onAddClose}
          onAdd={onAddSubmit}
        />
      ) : null}

      {pendingDelete ? (
        <DeleteOverrideDialog
          override={pendingDelete.override}
          variant={pendingDelete.type}
          isPending={removeMutation.isPending}
          onCancel={onCancelDelete}
          onConfirm={onConfirmDelete}
        />
      ) : null}
    </div>
  )
}
